#!/usr/bin/env bash
# Historical R-N5-CONSUMERS runner (model-free).
# Default TIP is consumer pin 90939f157fcb33606c0f5ccfbffbc10b9e51e64a.
# That pin has evaluate, compare, and receipt. It does not have diagnose.
# INPUT_B64 is the retained fixture bundle, byte-identical to
# requester-changed-bundle.json. The example.com title strings are
# constructed fixture input, not an observed website change or customer demand.
# Caller-owned local files only. No hosted upload, and sourceUri is not fetched.
# There is no INPUT_SRC override.
# Overrides: TIP, REPO_URL, FETCH_REF, ROOT, RUN_OUT, WORKDIR.
set -euo pipefail

TIP="${TIP:-90939f157fcb33606c0f5ccfbffbc10b9e51e64a}"
REPO_URL="${REPO_URL:-https://github.com/epistemedeus/samedaydesk.git}"
FETCH_REF="${FETCH_REF:-codex/h136010-machine-release-20261103}"
ROOT="${ROOT:-/tmp/n4-team/taskecon}"
RUN_OUT="${RUN_OUT:-/tmp/n4-team/taskecon-rn5-out}"
WORKDIR="${WORKDIR:-/tmp/n4-team/rn5-consumers-run}"

mkdir -p "$(dirname "$ROOT")" "$RUN_OUT" "$WORKDIR"

# Embedded requester-changed-bundle.json (base64)
INPUT_B64=''
INPUT_COPY="${WORKDIR}/requester-changed-bundle.json"
printf '%s' "$INPUT_B64" | base64 -d > "$INPUT_COPY"

if [[ ! -d "$ROOT/.git" ]]; then
  git clone --filter=blob:none "$REPO_URL" "$ROOT"
fi

(
  cd "$ROOT"
  git fetch --prune origin "$FETCH_REF" "$TIP" || git fetch origin "$TIP" || git fetch origin
  git checkout --detach "$TIP"
  HEAD="$(git rev-parse HEAD)"
  if [[ "$HEAD" != "$TIP" ]]; then
    echo "checkout mismatch: HEAD=$HEAD expected=$TIP" >&2
    exit 3
  fi
  if [[ ! -f tools/task-bundle-economics/cli.mjs ]]; then
    echo "missing tools/task-bundle-economics/cli.mjs at $HEAD" >&2
    exit 4
  fi
  printf '%s\n' "$HEAD" > "$RUN_OUT/HEAD.txt"
)

RECEIPT_OUT="${RUN_OUT}/requester-receipt.json"

run_one() {
  local name="$1"
  shift
  set +e
  "$@" > "${RUN_OUT}/${name}.stdout" 2> "${RUN_OUT}/${name}.stderr"
  local ec=$?
  set -e
  printf '%s\n' "$ec" > "${RUN_OUT}/${name}.exit"
  printf '%s\n' "$ec"
}

cd "$ROOT"
EVAL_EXIT="$(run_one evaluate node tools/task-bundle-economics/cli.mjs evaluate --input "$INPUT_COPY")"
COMPARE_EXIT="$(run_one compare node tools/task-bundle-economics/cli.mjs compare --input "$INPUT_COPY")"
RECEIPT_EXIT="$(run_one receipt node tools/task-bundle-economics/cli.mjs receipt --input "$INPUT_COPY" --out "$RECEIPT_OUT")"

SUMMARY=$(
  cat <<SUM
SUMMARY
tip=${TIP}
head=$(cat "${RUN_OUT}/HEAD.txt")
root=${ROOT}
input_copy=${INPUT_COPY}
evaluate_exit=${EVAL_EXIT}
compare_exit=${COMPARE_EXIT}
receipt_exit=${RECEIPT_EXIT}
receipt_out=${RECEIPT_OUT}
run_out=${RUN_OUT}
bundleDecision=$(node -e 'const j=require("fs").readFileSync(process.argv[1],"utf8"); const o=JSON.parse(j); process.stdout.write((o.bundleDecision&&o.bundleDecision.action)||"?")' "${RUN_OUT}/evaluate.stdout" 2>/dev/null || echo "?")
SUM
)
printf '%s\n' "$SUMMARY" | tee "${RUN_OUT}/SUMMARY.txt"

if [[ "$EVAL_EXIT" != "0" || "$COMPARE_EXIT" != "0" || "$RECEIPT_EXIT" != "0" ]]; then
  exit 1
fi
exit 0
